from fastapi import APIRouter, Body, Depends

from modules.operationalNotices import (
    active_operationalNotices_sp, all_operationalNotices_sp, operationalNotices_sp,
)
from security.session_tokens import require_company_rows_or_platform_admin

# Generated by posgmo-factory (PRD tests/prd_operationalNotice.json); guards added by hand.
# Write: admin/manager of that company (or SmartLoans admin). List: staff of that company.
# Active: same, or X-Worker-Key — LoanAgents_SmartLoans reads it by companyId (+ branchId).
_ADMIN_ROLES = {"admin", "manager"}
_STAFF_ROLES = {"admin", "manager", "employee", "business"}
_write_guard = require_company_rows_or_platform_admin("operationalNotices", _ADMIN_ROLES, allow_worker_key=False)
_list_guard = require_company_rows_or_platform_admin("operationalNotices", _STAFF_ROLES, allow_worker_key=False)
_active_guard = require_company_rows_or_platform_admin("operationalNotices", _STAFF_ROLES, allow_worker_key=True)

router = APIRouter()

with open("./docs_description/operationalNotices.txt", "r", encoding="utf-8") as file:
    notices_docstring = file.read()
with open("./docs_description/operationalNotices_all.txt", "r", encoding="utf-8") as file:
    notices_all_docstring = file.read()
with open("./docs_description/operationalNotices_active.txt", "r", encoding="utf-8") as file:
    notices_active_docstring = file.read()


@router.post("/operationalNotices", summary="operationalNotices: publish / update / finalize a company notice",
             description=notices_docstring)
def operationalNotices(json_file: dict = Body(...), claims: dict | None = Depends(_write_guard)):
    rows = json_file.get("operationalNotices") or [{}]
    # Who published / changed / finalized it comes from the signed token, never from the body.
    rows[0]["updatedByUserId"] = int(claims["sub"]) if claims and str(claims.get("sub", "")).isdigit() else None
    return operationalNotices_sp(json_file)


@router.post("/all_operationalNotices", summary="all operational notices of a company (POS)",
             description=notices_all_docstring, dependencies=[Depends(_list_guard)])
def all_operationalNotices(json_file: dict = Body(...)):
    return all_operationalNotices_sp(json_file)


@router.post("/active_operationalNotices", summary="notices that apply today or soon (agents)",
             description=notices_active_docstring, dependencies=[Depends(_active_guard)])
def active_operationalNotices(json_file: dict = Body(...)):
    return active_operationalNotices_sp(json_file)
